// Generated from the disc's Cyclic.MHK and Anims.MHK: the Spray Can's picture sets. Do not edit.

export interface KidPixSpraySet {
  /** "shapes" are Kid Pix's 3D shapes; "moving" is its moving paint, each animation where it comes to rest. */
  kind: "shapes" | "moving";
  name: string;
  /** Sheet under /kidpix/spray/, without its extension; a moving set has an .m4a of its clips beside it. */
  file: string;
  /**
   * Each picture in the sheet: x, y, width, height. Moving paint adds where its corner lands from
   * the pointer (x, y) and which of the set's clips it plays (-1 for none).
   */
  frames: readonly (readonly number[])[];
  /** Moving paint: each clip in the set's sound file, as start and length in seconds. */
  clips?: readonly (readonly [number, number])[];
}

